const teachingLoadByProgramme = `-- name: TeachingLoadByProgramme :many
WITH load AS (
    SELECT ci.programme_id, m.home_programme_id,
           COALESCE(SUM(ip.teaching_hours) FILTER (WHERE ip.taught_by IS NULL), 0)::float8 AS hours,
           COUNT(DISTINCT ci.id)::int AS instances,
           (COUNT(DISTINCT ci.id) FILTER (WHERE m.kind = 'FWP_PLACEHOLDER'))::int AS fwp_instances,
           COALESCE(SUM(ip.teaching_hours)
                    FILTER (WHERE m.kind = 'FWP_PLACEHOLDER' AND ip.taught_by IS NULL), 0)::float8
               AS fwp_hours,
           (COUNT(ip.id) FILTER (WHERE ip.teaching_hours IS NULL AND ip.taught_by IS NULL))::int
               AS parts_without_hours,
           COALESCE(SUM(ip.teaching_hours) FILTER (WHERE ip.taught_by IS NOT NULL), 0)::float8
               AS external_hours
    FROM course_instance ci
    JOIN semester s ON s.id = ci.semester_id
    JOIN module m ON m.id = ci.module_id
    LEFT JOIN instance_part ip ON ip.course_instance_id = ci.id
    WHERE s.code = $1::text
    GROUP BY ci.programme_id, m.home_programme_id
)
SELECT p.id AS programme_id, p.code AS programme_code, p.title AS programme_title,
       p.active AS programme_active, p.planning_status AS programme_planning_status,
       hp.id AS home_id, hp.code AS home_code, hp.title AS home_title,
       hp.active AS home_active, hp.planning_status AS home_planning_status,
       COALESCE(l.hours, 0)::float8 AS hours,
       COALESCE(l.instances, 0)::int AS instances,
       COALESCE(l.fwp_instances, 0)::int AS fwp_instances,
       COALESCE(l.fwp_hours, 0)::float8 AS fwp_hours,
       COALESCE(l.parts_without_hours, 0)::int AS parts_without_hours,
       COALESCE(l.external_hours, 0)::float8 AS external_hours
FROM programme p
LEFT JOIN load l ON l.programme_id = p.id
LEFT JOIN programme hp ON hp.id = l.home_programme_id
WHERE p.planning_status = 'PLANNED' OR l.programme_id IS NOT NULL
ORDER BY p.code, hp.code NULLS FIRST
`

type TeachingLoadByProgrammeRow struct {
	ProgrammeID             uuid.UUID
	ProgrammeCode           string
	ProgrammeTitle          string
	ProgrammeActive         bool
	ProgrammePlanningStatus string
	HomeID                  uuid.NullUUID
	HomeCode                *string
	HomeTitle               *string
	HomeActive              *bool
	HomePlanningStatus      *string
	Hours                   float64
	Instances               int32
	FwpInstances            int32
	FwpHours                float64
	PartsWithoutHours       int32
	ExternalHours           float64
}

// The teaching a semester's demand costs, attributed to the programme whose instances hold it.
//
// Whoever holds the parts pays (decided with the faculty on 2026-10-16). A module has one home in
// the examination office's catalogue — Analysis belongs to IF and appears in the regulations of
// DC, IC and GS as well — and charging every hour of it to IF made IF pay for the Analysis DC
// plans for itself. The spreadsheet before this tool had an IF and a DC variant for exactly that.
// Here the variant is the instance: DC's own Analysis holds its own parts and costs DC; a cohort
// that joins IF's event instead is covered, holds no parts, and costs nothing — IF, holding the
// event, pays for it.
//
// One row per (programme of the instance, home programme of the module). The split by home comes
// along, because "how much of what we pay for is other programmes' modules" is the import figure.
//
// A plain SUM over the parts is right without DISTINCT: every part belongs to exactly one
// instance, a lecture held for sibling cohorts is one part, and a covered cohort holds none.
// Parts with no hours stated count zero and are counted, so that an unfinished split cannot pass
// for a light semester.
//
// A part another faculty teaches (instance_part.taught_by, migration 29) is not this faculty's
// teaching and stays out of every figure above. Its hours come along as external_hours, beside
// the rest rather than subtracted from it: "how much of what our students attend does somebody
// else give" is a question the dean's office asks, and a part without hours that is not ours to
// state is not an unfinished split.
//
// Every planned programme is listed even with nothing declared — a programme that has not started
// is the row the dean's office is looking for — and any other programme only when its instances
// hold teaching here.
func (q *Queries) TeachingLoadByProgramme(ctx context.Context, semester string) ([]TeachingLoadByProgrammeRow, error) {
	rows, err := q.db.Query(ctx, teachingLoadByProgramme, semester)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TeachingLoadByProgrammeRow{}
	for rows.Next() {
		var i TeachingLoadByProgrammeRow
		if err := rows.Scan(
			&i.ProgrammeID,
			&i.ProgrammeCode,
			&i.ProgrammeTitle,
			&i.ProgrammeActive,
			&i.ProgrammePlanningStatus,
			&i.HomeID,
			&i.HomeCode,
			&i.HomeTitle,
			&i.HomeActive,
			&i.HomePlanningStatus,
			&i.Hours,
			&i.Instances,
			&i.FwpInstances,
			&i.FwpHours,
			&i.PartsWithoutHours,
			&i.ExternalHours,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const unsharePartsOfInstance = `-- name: UnsharePartsOfInstance :exec
UPDATE instance_part
SET serves_sibling_tracks = false, updated_at = now()
WHERE course_instance_id = $1 AND serves_sibling_tracks
`

// The pieces of a shared part are shared too, and stop being shared with it.
func (q *Queries) UnsharePartsOfInstance(ctx context.Context, courseInstanceID uuid.UUID) error {
	_, err := q.db.Exec(ctx, unsharePartsOfInstance, courseInstanceID)
	return err
}

const updateCourseInstance = `-- name: UpdateCourseInstance :exec
UPDATE course_instance
SET track = $2,
    programme_semester = $3,
    updated_at = now()
WHERE id = $1
`

type UpdateCourseInstanceParams struct {
	ID                uuid.UUID
	Track             string
	ProgrammeSemester *int32
}

// The two things about an instance that are editable: which cohort it is, and which year.
//
// The module, the programme and the semester are not. Changing one of those is not an edit of
// this instance, it is a different instance — and its parts, and later its wishes, belong to the
// one that was declared.
func (q *Queries) UpdateCourseInstance(ctx context.Context, arg UpdateCourseInstanceParams) error {
	_, err := q.db.Exec(ctx, updateCourseInstance, arg.ID, arg.Track, arg.ProgrammeSemester)
	return err
}

const updateCourseInstanceFormat = `-- name: UpdateCourseInstanceFormat :exec
UPDATE course_instance ci
SET delivery = $1,
    taught_in_english = NULLIF($2::boolean,
                               COALESCE(m.teaching_language = 'EN', false)),
    updated_at = now()
FROM module m
WHERE ci.id = $3 AND m.id = ci.module_id
`

type UpdateCourseInstanceFormatParams struct {
	Delivery        string
	TaughtInEnglish *bool
	ID              uuid.UUID
}

// How a cohort is taught: in a block or across the semester, and whether in English.
//
// On its own for the same reason as the note: nothing else that writes a cohort has these to
// state. The language is stored only where it differs from what the catalogue says for the
// module — NULLIF turns "English, and the catalogue says English" into "as the catalogue says",
// so that a later correction of the catalogue still reaches this cohort. A NULL argument is the
// explicit "as the catalogue says".
func (q *Queries) UpdateCourseInstanceFormat(ctx context.Context, arg UpdateCourseInstanceFormatParams) error {
	_, err := q.db.Exec(ctx, updateCourseInstanceFormat, arg.Delivery, arg.TaughtInEnglish, arg.ID)
	return err
}

const updateCourseInstanceNote = `-- name: UpdateCourseInstanceNote :exec
UPDATE course_instance
SET note = $2,
    updated_at = now()
WHERE id = $1
`

type UpdateCourseInstanceNoteParams struct {
	ID   uuid.UUID
	Note string
}

// The note beside a row, on its own rather than as a third column of UpdateCourseInstance.
//
// Renaming a cohort and duplicating one both go through UpdateCourseInstance and have no note to
// state; a statement that took one would make each of them restate what is there, and the one
// that forgot would blank it. The planning table writes the note where it writes the cohort year,
// and that is the only writer.
func (q *Queries) UpdateCourseInstanceNote(ctx context.Context, arg UpdateCourseInstanceNoteParams) error {
	_, err := q.db.Exec(ctx, updateCourseInstanceNote, arg.ID, arg.Note)
	return err
}

const updateCourseInstanceTopic = `-- name: UpdateCourseInstanceTopic :exec
UPDATE course_instance
SET topic = $1,
    updated_at = now()
WHERE id = $2
`

type UpdateCourseInstanceTopicParams struct {
	Topic *string
	ID    uuid.UUID
}

// Which seminar a cohort of an umbrella module is. NULL takes the topic away.
//
// On its own for the same reason as the note and the format: nothing else that writes a cohort
// has a topic to state, and a statement that took one would make each of them restate it.
func (q *Queries) UpdateCourseInstanceTopic(ctx context.Context, arg UpdateCourseInstanceTopicParams) error {
	_, err := q.db.Exec(ctx, updateCourseInstanceTopic, arg.Topic, arg.ID)
	return err
}

